from fastapi import APIRouter, HTTPException, Depends
from pydantic import BaseModel
from datetime import datetime
from sdk.feast_client import FeastClient
from monitoring.drift_detector import DriftDetector
from serving.redis_adapter import redis_client
from security.auth import get_current_user

router = APIRouter()
feast_client = FeastClient()
detector = DriftDetector()

class FeatureRegisterRequest(BaseModel):
    name: str
    version: str
    owner: str
    source_table: str
    description: str
    tags: list[str]

class FeatureQueryRequest(BaseModel):
    entity_ids: list[str]
    feature_names: list[str]
    timestamp: datetime | None = None

class MonitoringReportRequest(BaseModel):
    feature_name: str
    offline_stats: dict
    online_stats: dict
    timestamp: datetime

class AccessAssignRequest(BaseModel):
    team: str
    feature_name: str
    access_level: str

@router.post('/api/features/register')
def register_feature(req: FeatureRegisterRequest, user=Depends(get_current_user)):
    try:
        feature_id = feast_client.register_feature(
            name=req.name, version=req.version, owner=req.owner,
            source_table=req.source_table, description=req.description,
            tags=req.tags, registered_by=user
        )
        return {"status": "success", "feature_id": feature_id, "version": req.version}
    except Exception as e:
        raise HTTPException(status_code=500, detail=str(e))

@router.get('/api/features/query')
def query_features(req: FeatureQueryRequest):
    try:
        results = feast_client.get_features(req.entity_ids, req.feature_names, req.timestamp)
        return {"features": results}
    except Exception as e:
        raise HTTPException(status_code=500, detail=str(e))

@router.post('/api/features/monitoring/report')
def report_monitoring(req: MonitoringReportRequest):
    try:
        drift_detected, alert_id = detector.evaluate_drift(req.feature_name, req.offline_stats, req.online_stats)
        return {"status": "processed", "drift_detected": drift_detected, "alert_id": alert_id}
    except Exception as e:
        raise HTTPException(status_code=500, detail=str(e))

@router.post('/api/access/assign')
def assign_access(req: AccessAssignRequest, user=Depends(get_current_user)):
    try:
        feast_client.assign_access(req.team, req.feature_name, req.access_level)
        return {"status": "success", "assigned_to": req.team}
    except Exception as e:
        raise HTTPException(status_code=500, detail=str(e))

import redis
import json
from time import time

redis_client = redis.StrictRedis(host='localhost', port=6379, db=0, decode_responses=True)

class RedisFeatureServing:
    def __init__(self):
        self.client = redis_client

    def get_feature(self, entity_id, feature_name):
        start = time()
        value = self.client.get(f'{entity_id}:{feature_name}')
        latency_ms = (time() - start) * 1000
        if value is None:
            raise ValueError('Feature not found')
        if latency_ms > 10:
            print(f'Latency warning: {latency_ms}ms')
        return {'entity_id': entity_id, 'feature_name': feature_name, 'value': json.loads(value), 'latency_ms': latency_ms}

    def set_feature(self, entity_id, feature_name, value):
        self.client.set(f'{entity_id}:{feature_name}', json.dumps(value))

import math
import uuid

class DriftDetector:
    def evaluate_drift(self, feature_name, offline_stats, online_stats):
        try:
            mean_diff = abs(offline_stats['mean'] - online_stats['mean'])
            std_diff = abs(offline_stats['std'] - online_stats['std'])
            drift_detected = mean_diff > (0.1 * offline_stats['std']) or std_diff > (0.1 * offline_stats['std'])
            alert_id = str(uuid.uuid4()) if drift_detected else None
            if drift_detected:
                print(f'Drift detected in {feature_name} - alert {alert_id}')
            return drift_detected, alert_id
        except Exception as e:
            raise Exception(f'Drift detection error: {e}')

from fastapi.security import OAuth2PasswordBearer
from fastapi import Depends, HTTPException

oauth2_scheme = OAuth2PasswordBearer(tokenUrl='token')

VALID_TOKENS = {'valid-token': 'ml_user'}

def get_current_user(token: str = Depends(oauth2_scheme)):
    if token not in VALID_TOKENS:
        raise HTTPException(status_code=401, detail='Invalid authentication token')
    return VALID_TOKENS[token]
